Como no tienes computadora, usa esta versión: es una página web que se instala en Android desde el navegador Chrome y funciona como una app. Hace lo mismo: YouTube incrustado, letra que avanza sola y modo de captura de tiempos. Ignora las secciones de Flutter de arriba.

## A. Crear los archivos desde el celular

1. Crea una cuenta gratuita en https://github.com desde Chrome.
2. Toca el signo más y elige New repository. Ponle el nombre `alabanza`, márcalo como Public y toca Create repository.
3. Toca Add file, luego Create new file, y llama al primer archivo `index.html`. Pega el código de la sección B y toca Commit changes.
4. Repite con un segundo archivo llamado `manifest.json`, con el código de la sección C.
5. Crea un tercer archivo llamado `sw.js`, con el código de la sección D.

## B. Archivo index.html

```html
<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="theme-color" content="#111111">
<link rel="manifest" href="manifest.json">
<title>Alabanza Karaoke</title>
<style>
  * { box-sizing: border-box; }
  body { margin: 0; font-family: sans-serif; background: #111; color: #eee; }
  header { display: flex; align-items: center; gap: 10px; padding: 12px 16px; background: #1e1e1e; }
  header h1 { flex: 1; font-size: 20px; margin: 0; }
  button { background: #f5b301; color: #000; border: 0; border-radius: 10px; padding: 12px 16px; font-size: 16px; font-weight: bold; }
  button.sec { background: #333; color: #eee; }
  input, textarea { width: 100%; padding: 12px; margin: 6px 0; border-radius: 8px; border: 1px solid #444; background: #222; color: #eee; font-size: 16px; }
  textarea { min-height: 260px; }
  .pantalla { display: none; }
  .pantalla.activa { display: block; }
  .cancion { display: flex; align-items: center; padding: 16px; border-bottom: 1px solid #333; font-size: 20px; }
  .cancion span { flex: 1; }
  .form { padding: 16px; }
  #contenedor { display: flex; flex-direction: column; height: calc(100vh - 62px); }
  #video { width: 100%; aspect-ratio: 16/9; background: #000; }
  #video iframe { width: 100%; height: 100%; }
  #letra { flex: 1; overflow-y: auto; padding: 40vh 16px; text-align: center; scroll-behavior: smooth; }
  .linea { font-size: 28px; line-height: 1.7; color: #777; transition: all .25s; }
  .linea.activa { font-size: 38px; font-weight: bold; color: #f5b301; }
  #botonMarcar { display: none; position: fixed; right: 20px; bottom: 20px; width: 90px; height: 90px; border-radius: 50%; font-size: 30px; }
  #botonMarcar.visible { display: block; }
  @media (min-width: 800px) {
    #contenedor { flex-direction: row; }
    #video { width: 40%; align-self: flex-start; margin-top: 20px; }
    #letra { flex: 1; }
    .linea { font-size: 36px; }
    .linea.activa { font-size: 52px; }
  }
</style>
</head>
<body>

<div id="lista" class="pantalla activa">
  <header><h1>Mis alabanzas</h1><button onclick="mostrar('nueva')">+ Nueva</button></header>
  <div id="canciones"></div>
</div>

<div id="nueva" class="pantalla">
  <header><button class="sec" onclick="mostrar('lista')">←</button><h1>Nueva canción</h1></header>
  <div class="form">
    <input id="titulo" placeholder="Título">
    <input id="url" placeholder="Enlace de YouTube">
    <textarea id="texto" placeholder="Letra, una línea por renglón"></textarea>
    <button onclick="guardarNueva()">Guardar</button>
  </div>
</div>

<div id="reproductor" class="pantalla">
  <header>
    <button class="sec" onclick="salir()">←</button>
    <h1 id="nombre"></h1>
    <button class="sec" id="btnCaptura" onclick="alternarCaptura()">⏱ Marcar</button>
  </header>
  <div id="contenedor">
    <div id="video"><div id="yt"></div></div>
    <div id="letra"></div>
  </div>
  <button id="botonMarcar" onclick="marcar()">🚩</button>
</div>

<script src="https://www.youtube.com/iframe_api"></script>
<script>
let canciones = JSON.parse(localStorage.getItem('canciones') || '[]');
let actual = null, indice = 0, player = null, reloj = null;
let captura = false, siguiente = 0, apiLista = false;

function onYouTubeIframeAPIReady() { apiLista = true; }

function mostrar(id) {
  document.querySelectorAll('.pantalla').forEach(p => p.classList.remove('activa'));
  document.getElementById(id).classList.add('activa');
  if (id === 'lista') pintarLista();
}

function guardarTodo() { localStorage.setItem('canciones', JSON.stringify(canciones)); }

function pintarLista() {
  const div = document.getElementById('canciones');
  div.innerHTML = '';
  if (!canciones.length) div.innerHTML = '<p style="padding:16px">Agrega tu primera alabanza con el botón Nueva.</p>';
  canciones.forEach((c, i) => {
    const f = document.createElement('div');
    f.className = 'cancion';
    f.innerHTML = '<span>🎵 ' + c.titulo + '</span>';
    f.querySelector('span').onclick = () => abrir(i);
    const b = document.createElement('button');
    b.className = 'sec'; b.textContent = '🗑';
    b.onclick = () => { if (confirm('¿Borrar esta canción?')) { canciones.splice(i, 1); guardarTodo(); pintarLista(); } };
    f.appendChild(b);
    div.appendChild(f);
  });
}

function extraerId(url) {
  url = url.trim();
  const m = url.match(/(?:youtu\.be\/|v=|embed\/|shorts\/)([A-Za-z0-9_-]{11})/);
  return m ? m[1] : url;
}

function guardarNueva() {
  const titulo = document.getElementById('titulo').value.trim();
  const lineas = document.getElementById('texto').value.split('\n').map(l => l.trim()).filter(l => l);
  if (!titulo || !lineas.length) { alert('Falta el título o la letra'); return; }
  canciones.push({ titulo, videoId: extraerId(document.getElementById('url').value), lineas, tiempos: lineas.map(() => -1) });
  guardarTodo();
  document.getElementById('titulo').value = '';
  document.getElementById('url').value = '';
  document.getElementById('texto').value = '';
  mostrar('lista');
}

function abrir(i) {
  if (!apiLista) { alert('Espera un momento, cargando YouTube...'); return; }
  actual = canciones[i];
  indice = 0; captura = false; siguiente = 0;
  document.getElementById('nombre').textContent = actual.titulo;
  document.getElementById('botonMarcar').classList.remove('visible');
  pintarLetra();
  mostrar('reproductor');
  if (player) player.destroy();
  document.getElementById('video').innerHTML = '<div id="yt"></div>';
  player = new YT.Player('yt', { videoId: actual.videoId, playerVars: { playsinline: 1, rel: 0 } });
  reloj = setInterval(actualizar, 250);
}

function salir() {
  clearInterval(reloj);
  if (player) { player.destroy(); player = null; }
  mostrar('lista');
}

function pintarLetra() {
  const l = document.getElementById('letra');
  l.innerHTML = '';
  actual.lineas.forEach((t, i) => {
    const d = document.createElement('div');
    d.className = 'linea'; d.id = 'l' + i; d.textContent = t;
    l.appendChild(d);
  });
}

function resaltar(i) {
  document.querySelectorAll('.linea').forEach(x => x.classList.remove('activa'));
  const el = document.getElementById('l' + i);
  if (el) { el.classList.add('activa'); el.scrollIntoView({ block: 'center', behavior: 'smooth' }); }
  indice = i;
}

function actualizar() {
  if (captura || !player || !player.getCurrentTime) return;
  const t = player.getCurrentTime();
  let idx = -1;
  for (let i = 0; i < actual.tiempos.length; i++) {
    if (actual.tiempos[i] >= 0 && actual.tiempos[i] <= t) idx = i;
  }
  if (idx >= 0 && idx !== indice) resaltar(idx);
}

function alternarCaptura() {
  captura = !captura;
  siguiente = 0;
  document.getElementById('botonMarcar').classList.toggle('visible', captura);
  document.getElementById('btnCaptura').textContent = captura ? '✓ Listo' : '⏱ Marcar';
  if (captura) { actual.tiempos = actual.lineas.map(() => -1); resaltar(0); }
  else guardarTodo();
}

function marcar() {
  if (siguiente >= actual.lineas.length) return;
  actual.tiempos[siguiente] = player.getCurrentTime();
  resaltar(siguiente);
  siguiente++;
  guardarTodo();
}

if ('serviceWorker' in navigator) navigator.serviceWorker.register('sw.js');
pintarLista();
</script>
</body>
</html>
